"use client";

// The channel-shortlist study (Nov 2026): strategies from the owner's three lists of YouTube channels (127 unique),
// each video read from its transcript in the Trading Video Lab and written as exact rules. Data: ./shortlistData.ts,
// generated by backend/research/youtube_shortlist_2026_11/ze_export.py. The coded strategies trade on the paper desk
// (source youtube_shortlist, Rs 10 lakh each, simulated orders on real market data) from SL_META.paperStart.
import { useMemo, useState } from "react";
import GlassPanel from "../../components/GlassPanel";
import type { Account, Summary } from "./PaperDesk";
import { SL, SL_CHANNELS, SL_META, type SlRule, type SlStrategy } from "./shortlistData";

const TOPICS = [
  { id: "india_index", label: "Indian index (Nifty, Bank Nifty)",
    note: "Nifty and Bank Nifty setups on one-minute index data. Option-buying videos trade the index as a labelled proxy (the desk has no intraday option premiums). Index rows carry no real volume, so VWAP there is time-weighted." },
  { id: "india_stocks", label: "Indian stocks",
    note: "NSE stock setups on the desk's stock pool (5- and 15-minute bars) and swing setups on daily bars (long only: cash stocks cannot be held short overnight). The daily panel carries no volume, so daily volume rules are dropped and say so." },
  { id: "crypto", label: "Bitcoin and gold",
    note: "Bitcoin on Delta Exchange's BTCUSD perpetual (out by 23:55 UTC) and gold on Delta's XAUTUSD. Bitcoin carries real volume." },
  { id: "forex_us", label: "Forex and Nasdaq",
    note: "EUR/USD and GBP/USD from the desk's FX futures minutes, the Nasdaq 100 cash session (09:30-16:00 New York). These feeds carry no real volume: VWAP is time-weighted." },
] as const;
type TopicId = (typeof TOPICS)[number]["id"];

const rupees = (x: number) => "₹" + Math.round(x).toLocaleString("en-IN");
const pct = (x: number) => `${x >= 0 ? "+" : ""}${x.toFixed(2)}%`;

function sec(t: string): number {
  const p = t.split(":").map(Number);
  return p.length === 3 ? p[0] * 3600 + p[1] * 60 + p[2] : p[0] * 60 + p[1];
}

function Times({ video, times }: { video: string; times: string[] }) {
  if (!times.length) return null;
  return (
    <span className="sl-times">
      {times.map((t, i) => (
        <a key={`${t}-${i}`} href={`https://youtu.be/${video}?t=${sec(t)}`} target="_blank" rel="noreferrer">{t}</a>
      ))}
    </span>
  );
}

function grouped(rules: SlRule[]): [string, SlRule[]][] {
  const out: [string, SlRule[]][] = [];
  for (const r of rules) {
    const last = out[out.length - 1];
    if (last && last[0] === r.label) last[1].push(r);
    else out.push([r.label, [r]]);
  }
  return out;
}

function Paper({ account, started }: { account?: Account; started: boolean }) {
  if (!account) return <div className="sl-paper">Paper account: not on the desk yet.</div>;
  if (!started) return <div className="sl-paper">Paper account: {rupees(account.capital || 1_000_000)}, armed — trading starts at {new Date(SL_META.paperStart).toLocaleString("en-IN", { timeZone: "Asia/Kolkata", dateStyle: "medium", timeStyle: "short" })} IST.</div>;
  const traded = account.closed + account.open > 0;
  return (
    <div className="sl-paper">
      Paper account: {rupees(account.equity)}{" "}
      {traded ? (
        <>
          <b className={account.return_pct >= 0 ? "sl-up" : "sl-down"}>{pct(account.return_pct)}</b> · {account.closed} closed, {account.wins} won
          {account.open ? ` · ${account.open} open` : ""}
        </>
      ) : <>· no trades yet</>}
    </div>
  );
}

function Card({ s, account, started }: { s: SlStrategy; account?: Account; started: boolean }) {
  const stated = s.rules.filter((r) => r.tag !== "A");
  const ours = s.rules.filter((r) => r.tag === "A");
  const gaps = s.vague.length + s.unclear.length;
  return (
    <div className="ps-card sl-card">
      <div className="ps-card-top">
        <span className="ps-fam up">{s.id} · {s.version}</span>
        <span className="sl-dim">{s.channel}</span>
      </div>
      <div className="ps-card-name">{s.name}</div>
      <div className="sl-line">{s.markets.join(" · ")} · {s.timeframes.join(", ")}{s.overnight ? " · holds overnight (daily)" : " · intraday"}</div>
      {s.proxy && <div className="sl-proxy">{s.proxy}.</div>}
      <div className="sl-line">
        <a href={`https://youtu.be/${s.video}`} target="_blank" rel="noreferrer">{s.title || s.video}</a>
        <span className="sl-dim">{s.uploaded ? ` · ${s.uploaded}` : ""}{s.minutes ? ` · ${s.minutes} min` : ""}</span>
      </div>
      <p className="sl-sum">{s.summary}</p>
      <div className="sl-tags">
        <span className={`sl-tag ${s.readiness === "ready" ? "ok" : "warn"}`}>{s.readiness === "ready" ? "Every rule stated" : "Coded with documented assumptions"}</span>
        {s.checks && (
          <span className={`sl-tag ${s.checks.lookahead && s.checks.fills ? "ok" : "bad"}`}>
            {s.checks.lookahead && s.checks.fills ? "Look-ahead and fill checks passed" : "Code check failed"}
          </span>
        )}
        <span className="sl-tag">Not backtested</span>
      </div>
      <Paper account={account} started={started} />
      <details className="sl-sec">
        <summary>Rules from the video ({stated.length})</summary>
        {grouped(stated).map(([label, rs]) => (
          <div key={label} className="sl-group">
            <div className="sl-glabel">{label}</div>
            <ul className="sl-rules">
              {rs.map((r, i) => <li key={i}><span className={`sl-t ${r.tag}`}>{r.tag}</span> {r.text} <Times video={s.video} times={r.times} /></li>)}
            </ul>
          </div>
        ))}
      </details>
      {ours.length > 0 && (
        <details className="sl-sec">
          <summary>Our assumptions used to code it ({ours.length})</summary>
          <ul className="sl-rules">
            {ours.map((r, i) => <li key={i}><span className="sl-t A">A</span> <b>{r.label}:</b> {r.text}</li>)}
          </ul>
          <p className="sl-dim">These are the research team&apos;s choices, not the creator&apos;s words: they fill the gaps the video leaves so the rule can run.</p>
        </details>
      )}
      {gaps > 0 && (
        <details className="sl-sec">
          <summary>Missing or ambiguous in the video ({gaps})</summary>
          <ul className="sl-rules">
            {s.vague.map((v, i) => <li key={`v${i}`}>&ldquo;{v.term}&rdquo; <Times video={s.video} times={v.at ? [v.at] : []} />: {v.why}. Coded as: {v.suggestion}.</li>)}
            {s.unclear.map((u, i) => <li key={`u${i}`}>Open question: {u}</li>)}
          </ul>
        </details>
      )}
      {(s.claims.length > 0 || s.examples.length > 0) && (
        <details className="sl-sec">
          <summary>Claims and examples in the video ({s.claims.length + s.examples.length})</summary>
          <ul className="sl-rules">
            {s.claims.map((c, i) => <li key={`c${i}`}>Claim: {c.value}{c.period ? ` (${c.period})` : ""} <Times video={s.video} times={c.at ? [c.at] : []} /></li>)}
            {s.examples.map((x, i) => (
              <li key={`x${i}`}>
                Example{x.date ? ` ${x.date}` : ""}: {x.instrument} {x.direction} — {x.setup}; entry {x.entry || "—"}, stop {x.stop || "—"}, target {x.target || "—"} → {x.outcome}
                {x.note ? ` (${x.note})` : ""} <Times video={s.video} times={x.at ? [x.at] : []} />
              </li>
            ))}
          </ul>
          <p className="sl-dim">Quoted as said and not verified.</p>
        </details>
      )}
      {s.checks && <div className="sl-dim">Code check windows: {s.checks.signals} signals, {s.checks.trades} simulated fills (a correctness check, not a result).</div>}
    </div>
  );
}

export default function Shortlist({ summary }: { summary: Summary | null; error?: string | null }) {
  const [topic, setTopic] = useState<TopicId>("india_index");
  const [q, setQ] = useState("");
  const byId = useMemo(() => Object.fromEntries((summary?.accounts ?? []).map((a) => [a.id, a])) as Record<string, Account>, [summary]);
  const started = Date.now() >= new Date(SL_META.paperStart).getTime();
  const T = TOPICS.find((t) => t.id === topic)!;
  const ql = q.trim().toLowerCase();
  const inTopic = SL.filter((s) => s.topic === topic);
  const coded = inTopic.filter((s) => s.status === "coded" && (!ql || `${s.id} ${s.name} ${s.channel} ${s.title}`.toLowerCase().includes(ql)));
  const blocked = inTopic.filter((s) => s.status !== "coded");
  const m = SL_META;
  const onDesk = SL.filter((s) => s.status === "coded" && byId[s.id]).length;
  return (
    <>
      <GlassPanel title="Channel shortlist — strategies from your 127 YouTube channels" note={`${m.coded} coded · paper trading · ₹10 lakh each`}>
        <p className="sl-intro">
          Your three channel lists merge into {m.channels} unique channels ({m.coveredBefore} of them studied before).{" "}
          {m.picked} strategy videos were picked from the channels&apos; uploads by title (most specific setup first). {m.analysed} have been read in full from
          their transcripts so far, giving {m.strategies} strategies: {m.coded} coded as exact rules (version v1) and {m.blocked} with no testable rule or needing
          data the desk lacks. All {m.checked} coded strategies passed the look-ahead and fill checks; none is backtested. They paper trade on the desk with
          ₹10 lakh each (simulated orders on real prices) from {new Date(m.paperStart).toLocaleString("en-IN", { timeZone: "Asia/Kolkata", dateStyle: "medium", timeStyle: "short" })} IST
          {summary ? ` — ${onDesk} of ${m.coded} accounts are on the desk.` : "."} The other {m.queued} picked videos are queued and are being read next.
        </p>
      </GlassPanel>
      <div className="ps-chips sl-topics">
        {TOPICS.map((t) => {
          const n = SL.filter((s) => s.topic === t.id);
          return (
            <button key={t.id} className={`ps-chip${topic === t.id ? " on" : ""}`} onClick={() => setTopic(t.id)}>
              {t.label} · {n.filter((s) => s.status === "coded").length} coded / {n.length}
            </button>
          );
        })}
        <input className="sl-q" placeholder="Search id, name, channel" value={q} onChange={(e) => setQ(e.target.value)} />
      </div>
      <p className="sl-note">{T.note}</p>
      <div className="ps-cards sl-cards">
        {coded.map((s) => <Card key={s.id} s={s} account={byId[s.id]} started={started} />)}
      </div>
      {blocked.length > 0 && (
        <GlassPanel title={`No account in ${T.label}`} note="no testable rule, or data the desk lacks">
          <ul className="sl-list">
            {blocked.map((s) => (
              <li key={s.id}>
                <b>{s.id} {s.name}</b> (<a href={`https://youtu.be/${s.video}`} target="_blank" rel="noreferrer">{s.channel || s.video}</a>) — {s.blockedReason || s.duplicateWhy}
              </li>
            ))}
          </ul>
        </GlassPanel>
      )}
      <details className="sl-sec sl-wide">
        <summary>All {SL_CHANNELS.length} channels: what was picked, read or skipped</summary>
        <table className="sl-table">
          <thead><tr><th>Channel</th><th>Uploads</th><th>Strategy titles</th><th>Videos (✓ read)</th></tr></thead>
          <tbody>
            {SL_CHANNELS.map((c) => (
              <tr key={c.key}>
                <td>{c.name}{c.star ? " ★" : ""}{c.earlier ? <span className="sl-dim"> · earlier: {c.earlier}</span> : null}</td>
                <td>{c.uploads}</td>
                <td>{c.strategyTitles}</td>
                <td>
                  {c.picked.length ? c.picked.map((p) => (
                    <span key={p.video} className="sl-pick">
                      <a href={`https://youtu.be/${p.video}`} target="_blank" rel="noreferrer">{p.analysed ? "✓ " : ""}{p.id ?? p.video}</a>
                    </span>
                  )) : <span className="sl-dim">{c.skip || "not picked in this round"}</span>}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </details>
      {/* global: the cards are a child component; every selector is sl-prefixed, so nothing outside this tab is touched. */}
      <style jsx global>{`
        .sl-intro { font-size: 13px; line-height: 1.6; color: var(--text-muted); margin: 0; }
        .sl-topics { margin: 14px 0 6px; align-items: center; }
        .sl-q { margin-left: auto; min-width: 200px; padding: 6px 10px; border-radius: 8px; border: 1px solid var(--panel-border);
          background: transparent; color: inherit; font-size: 12.5px; }
        .sl-note { font-size: 12.5px; color: var(--text-muted); margin: 4px 0 12px; line-height: 1.5; }
        .sl-cards { align-items: start; margin-bottom: 16px; }
        .sl-line { font-size: 12.5px; line-height: 1.5; overflow-wrap: anywhere; }
        .sl-dim { color: var(--text-muted); font-size: 11.5px; }
        .sl-sum { font-size: 12.5px; line-height: 1.55; margin: 0; color: var(--text-secondary); }
        .sl-proxy { font-size: 12px; padding: 6px 8px; border-radius: 6px; background: var(--warn-dim); color: var(--warn); }
        .sl-paper { font-size: 12.5px; padding: 6px 8px; border-radius: 6px; background: var(--canvas-soft); }
        .sl-up { color: var(--gain); }
        .sl-down { color: var(--loss); }
        .sl-tags { display: flex; flex-wrap: wrap; gap: 6px; }
        .sl-tag { font-size: 11px; padding: 2px 8px; border-radius: 999px; border: 1px solid var(--panel-border); color: var(--text-muted); }
        .sl-tag.ok { border-color: var(--gain); color: var(--gain); }
        .sl-tag.warn { border-color: var(--warn-border); color: var(--warn); }
        .sl-tag.bad { border-color: var(--loss); color: var(--loss); }
        .sl-sec { font-size: 12.5px; }
        .sl-sec summary { cursor: pointer; font-weight: 600; }
        .sl-wide { margin: 8px 0 16px; }
        .sl-group { margin-top: 6px; }
        .sl-glabel { font-size: 11px; font-weight: 800; letter-spacing: 0.04em; text-transform: uppercase; color: var(--text-muted); }
        .sl-rules { margin: 4px 0 6px; padding-left: 18px; line-height: 1.55; }
        .sl-rules li { margin-bottom: 4px; overflow-wrap: anywhere; }
        .sl-t { display: inline-block; min-width: 16px; text-align: center; font-size: 10px; font-weight: 800; border-radius: 4px; padding: 0 3px;
          border: 1px solid var(--panel-border); color: var(--text-muted); }
        .sl-t.E { border-color: var(--gain); color: var(--gain); }
        .sl-t.I { border-color: var(--purple); color: var(--purple); }
        .sl-t.A { border-color: var(--warn-border); color: var(--warn); }
        .sl-times a { margin-left: 6px; font-size: 11px; font-variant-numeric: tabular-nums; }
        .sl-list { font-size: 12.5px; line-height: 1.6; padding-left: 18px; margin: 0; }
        .sl-list li { margin-bottom: 8px; overflow-wrap: anywhere; }
        .sl-table { width: 100%; border-collapse: collapse; font-size: 12px; margin-top: 8px; }
        .sl-table th, .sl-table td { text-align: left; padding: 4px 6px; border-bottom: 1px solid var(--panel-border); vertical-align: top; }
        .sl-pick { margin-right: 8px; white-space: nowrap; }
      `}</style>
    </>
  );
}
